
# ============================================================
# PHASE 10.5: DECISION THRESHOLD ANALYSIS
# ============================================================
# Purpose:
# Compare different classification thresholds for the
# recall-focused Logistic Regression model.
#
# This experiment uses out-of-fold predictions so that each
# patient's probability is generated by a model that did not
# train on that patient's fold.
#
# IMPORTANT:
# This script does not modify or overwrite the saved model.
# ============================================================


# Import libraries for data processing and model evaluation.
from pathlib import Path

import numpy as np
import pandas as pd

from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.pipeline import Pipeline
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    roc_auc_score,
    confusion_matrix
)

# Import the existing custom IQR clipping transformer.
from iqr_clipper import IQRClipper


# ------------------------------------------------------------
# STEP 1: DEFINE PROJECT FILE PATHS
# ------------------------------------------------------------

# Find the main project directory.
PROJECT_ROOT = Path(__file__).resolve().parents[1]

# Define the dataset path.
DATA_PATH = PROJECT_ROOT / "data" / "diabetes.csv"

# Define the output directory and CSV file.
RESULTS_DIR = PROJECT_ROOT / "results"
OUTPUT_PATH = RESULTS_DIR / "threshold_analysis.csv"


# ------------------------------------------------------------
# STEP 2: LOAD AND PREPARE THE DATASET
# ------------------------------------------------------------

# Load the diabetes dataset into a Pandas DataFrame.
data = pd.read_csv(DATA_PATH)

# Separate the eight input features from the target column.
X = data.drop(columns=["Outcome"])

# Store the actual diabetes outcome values.
y = data["Outcome"]

# In this dataset, zero represents missing information for
# these five medical measurements.
zero_missing_columns = [
    "Glucose",
    "BloodPressure",
    "SkinThickness",
    "Insulin",
    "BMI"
]

# Replace invalid zero values with NaN.
# The imputer will estimate these missing values inside
# each cross-validation training fold.
X[zero_missing_columns] = X[zero_missing_columns].replace(0, np.nan)


# ------------------------------------------------------------
# STEP 3: BUILD THE RECALL-FOCUSED MODEL PIPELINE
# ------------------------------------------------------------

# Use the best recall-focused hyperparameters identified
# during the previous Logistic Regression tuning experiment.
#
# Pipeline order:
# IQR clipping -> Median imputation -> Standard scaling
# -> Logistic Regression.
#
# Every preprocessing step is fitted separately inside
# each cross-validation training fold.
model_pipeline = Pipeline([
    ("iqr_clipping", IQRClipper()),
    ("imputer", SimpleImputer(strategy="median")),
    ("scaler", StandardScaler()),
    ("model", LogisticRegression(
        C=0.01,
        class_weight="balanced",
        solver="liblinear",
        random_state=42,
        max_iter=2000
    ))
])


# ------------------------------------------------------------
# STEP 4: CONFIGURE STRATIFIED CROSS-VALIDATION
# ------------------------------------------------------------

# Create five folds while maintaining the class proportions.
cv = StratifiedKFold(
    n_splits=5,
    shuffle=True,
    random_state=42
)


# ------------------------------------------------------------
# STEP 5: GENERATE OUT-OF-FOLD PREDICTION PROBABILITIES
# ------------------------------------------------------------

# Generate probabilities for every patient.
# Each patient's probability comes from a model that did
# not use that patient's fold for training.
#
# method="predict_proba" returns probabilities for both
# classes: class 0 and class 1.
probabilities = cross_val_predict(
    model_pipeline,
    X,
    y,
    cv=cv,
    method="predict_proba",
    n_jobs=1
)

# Extract the probability of class 1 (diabetes risk class).
positive_probabilities = probabilities[:, 1]

# Calculate ROC-AUC once because it does not depend on
# the selected classification threshold.
overall_roc_auc = roc_auc_score(
    y,
    positive_probabilities
)


# ------------------------------------------------------------
# STEP 6: DEFINE THE THRESHOLDS TO BE TESTED
# ------------------------------------------------------------

# Test nine thresholds between 0.30 and 0.70.
thresholds = [
    0.30,
    0.35,
    0.40,
    0.45,
    0.50,
    0.55,
    0.60,
    0.65,
    0.70
]


# ------------------------------------------------------------
# STEP 7: EVALUATE EACH THRESHOLD
# ------------------------------------------------------------

# Store the evaluation results for every threshold.
results = []

# Repeat the evaluation using each threshold.
for threshold in thresholds:

    # Predict class 1 when its probability is at least
    # the current threshold; otherwise predict class 0.
    predicted_classes = (
        positive_probabilities >= threshold
    ).astype(int)

    # Calculate the confusion matrix in the order:
    # True Negative, False Positive,
    # False Negative, True Positive.
    tn, fp, fn, tp = confusion_matrix(
        y,
        predicted_classes,
        labels=[0, 1]
    ).ravel()

    # Calculate standard classification metrics.
    accuracy = accuracy_score(y, predicted_classes)

    precision = precision_score(
        y,
        predicted_classes,
        zero_division=0
    )

    recall = recall_score(
        y,
        predicted_classes,
        zero_division=0
    )

    f1 = f1_score(
        y,
        predicted_classes,
        zero_division=0
    )

    # Store all results for this threshold.
    results.append({
        "Threshold": threshold,
        "Accuracy": accuracy,
        "Precision": precision,
        "Recall": recall,
        "F1_Score": f1,
        "ROC_AUC": overall_roc_auc,
        "True_Negative": tn,
        "False_Positive": fp,
        "False_Negative": fn,
        "True_Positive": tp
    })


# ------------------------------------------------------------
# STEP 8: DISPLAY THE RESULTS
# ------------------------------------------------------------

# Convert the results list into a DataFrame.
results_df = pd.DataFrame(results)

# Display all metrics with four decimal places.
print("\nDECISION THRESHOLD ANALYSIS")
print("=" * 100)

print(
    results_df.to_string(
        index=False,
        float_format=lambda value: f"{value:.4f}"
    )
)


# ------------------------------------------------------------
# STEP 9: SAVE THE RESULTS
# ------------------------------------------------------------

# Create the results directory if it does not exist.
RESULTS_DIR.mkdir(
    parents=True,
    exist_ok=True
)

# Save the threshold comparison as a CSV file.
results_df.to_csv(
    OUTPUT_PATH,
    index=False
)

# Confirm where the results were saved.
print("\nAnalysis completed successfully.")
print(f"Results saved to: {OUTPUT_PATH}")
